INSERT INTO `english_tests` (`id`, `name`, `slug`, `shortName`, `shortDescription`, `longDescription`, `testType`, `provider`, `officialUrl`, `format`, `durationMinutes`, `durationDisplay`, `scoringSystem`, `resultTimeline`, `costSummary`, `validitySummary`, `bestFor`, `acceptanceSummary`, `difficultyLevel`, `status`, `isPopular`, `isFeatured`, `sortOrder`, `sourceUrl`, `sourceName`, `verifiedBy`, `verificationStatus`, `seoTitle`, `seoDescription`, `lastVerifiedAt`, `createdAt`, `updatedAt`)
SELECT 'test-ielts', 'IELTS', 'ielts', 'IELTS', 'International English Language Testing System — Academic', 'IELTS Academic is designed to assess English language proficiency for higher education. It evaluates Listening, Reading, Writing and Speaking in academic contexts. Requirements vary by country, visa route, university and course.', 'english_proficiency', 'IDP, British Council, Cambridge', 'https://ielts.org', 'Paper / Computer', 165, 'About 2h 45m', 'IELTS bands 0–9', 'Computer: usually 1–5 days; paper: usually 13 days. Local delivery arrangements apply.', 'Fees depend on location, delivery mode and booking date. View the provider booking price before payment.', '2 years — Check official provider', 'UK, Australia, Canada, Ireland, New Zealand, USA, Europe — University admission', 'Confirm the exact exam, delivery mode and minimum score with your university. Visa evidence rules are separate; a university offer does not confirm visa eligibility.', 'Moderate to Challenging', 'active', 1, 1, 1, 'https://ielts.org/take-a-test/why-choose-ielts/ways-to-take-ielts', 'IELTS Official', 'Official-source editorial review', 'verified', 'IELTS Preparation for Study Abroad | Requirements, Test Format & Guidance | ALO Education', 'Prepare for IELTS Academic with structured guidance, target score planning, and university requirement checks. Expert support from ALO Education.', '2026-10-26 00:00:00.000', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)
WHERE NOT EXISTS (SELECT 1 FROM `english_tests` WHERE `slug` = 'ielts' OR `id` = 'test-ielts');

INSERT INTO `english_tests` (`id`, `name`, `slug`, `shortName`, `shortDescription`, `longDescription`, `testType`, `provider`, `officialUrl`, `format`, `durationMinutes`, `durationDisplay`, `scoringSystem`, `resultTimeline`, `costSummary`, `validitySummary`, `bestFor`, `acceptanceSummary`, `difficultyLevel`, `status`, `isPopular`, `isFeatured`, `sortOrder`, `sourceUrl`, `sourceName`, `verifiedBy`, `verificationStatus`, `seoTitle`, `seoDescription`, `lastVerifiedAt`, `createdAt`, `updatedAt`)
SELECT 'test-ielts-ukvi', 'IELTS UKVI', 'ielts-ukvi', 'IELTS UKVI', 'IELTS for UK Visas and Immigration — Secure English Language Test', 'IELTS for UKVI is a Secure English Language Test (SELT) approved by UK Visas and Immigration. Test content, format and scoring are identical to standard IELTS but delivered under UKVI security requirements with video recording. Required for certain UK visa routes. Requirements vary by country, visa route, university and course.', 'english_proficiency', 'IDP, British Council, Cambridge — UKVI SELT', 'https://ielts.org/take-a-test/your-results/ielts-for-ukvi', 'Paper / Computer — UKVI SELT Centre', 165, 'About 2h 45m (Academic / General Training)', 'IELTS bands 0–9', 'Depends on delivery mode and local test centre; confirm when booking.', 'Fees depend on location, delivery mode and booking date. View the provider booking price before payment.', '2 years — Check official UKVI guidance', 'UK Foundation, Pre-sessional, Below-degree, Certain visa routes', 'Confirm the exact exam, delivery mode and minimum score with your university. Visa evidence rules are separate; a university offer does not confirm visa eligibility.', 'Moderate to Challenging', 'active', 1, 1, 2, 'https://ielts.org/take-a-test/test-types/ielts-for-ukvi', 'UKVI Official Guidance', 'Official-source editorial review', 'verified', 'IELTS UKVI Preparation | UKVI SELT Requirements & Guidance | ALO Education', 'Understand IELTS for UKVI requirements, differences from standard IELTS, and UK visa guidance. ALO Education helps you choose the right SELT.', '2026-10-26 00:00:00.000', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)
WHERE NOT EXISTS (SELECT 1 FROM `english_tests` WHERE `slug` = 'ielts-ukvi' OR `id` = 'test-ielts-ukvi');

