SELECT 'test-pte', 'PTE Academic', 'pte-academic', 'PTE', 'Pearson Test of English Academic — Computer-based English test', 'PTE Academic is a fully computer-based English test with AI scoring, assessing Speaking & Writing, Reading and Listening. Widely accepted for university admission and visa routes. Acceptance varies by university, course and visa route.', 'english_proficiency', 'Pearson', 'https://www.pearsonpte.com', 'Computer — Test Centre', 120, 'About 2 hours', 'PTE score 10–90', 'Typically 2 days; some results take longer.', 'Fees depend on location, delivery mode and booking date. View the provider booking price before payment.', '2 years — Check official provider', 'UK, Australia, Canada, USA, Ireland, New Zealand — Fast results', 'Confirm the exact exam, delivery mode and minimum score with your university. Visa evidence rules are separate; a university offer does not confirm visa eligibility.', 'Moderate', 'active', 1, 1, 3, 'https://www.pearsonpte.com/pte-academic/', 'Pearson PTE Official', 'Official-source editorial review', 'verified', 'PTE Academic Preparation | Requirements, Format & Guidance | ALO Education', 'Prepare for PTE Academic with expert guidance, score planning and university acceptance checks. Fast results and AI scoring insights.', '2026-10-26 00:00:00.000', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)
