SELECT 'test-moi', 'MOI Guidance', 'moi', 'MOI', 'Medium of Instruction — Guidance resource, not an English proficiency test', 'Medium of Instruction (MOI) is a guidance resource explaining when universities may accept an MOI certificate as alternative to English proficiency tests. MOI is NOT an English proficiency test. Acceptance is strictly university and course specific and requires verification. Requirements vary by country, visa route, university and course. Check university-specific acceptance and official immigration guidance.', 'moi_guidance', 'University-specific — Guidance by ALO Education', 'https://aloeducation.com/language-prep/moi', 'Guidance Resource — Not a test', 0, 'Not applicable — Guidance resource', 'Not applicable — MOI is not a scored test', 'Not applicable — Guidance resource', 'Not applicable — Guidance resource', 'University-specific — Check official university page', 'Students with English-medium education background — University-specific MOI acceptance only', 'Strictly university-specific — Only where university officially confirms MOI acceptance — Check university course page', 'Guidance only', 'active', 0, 0, 15, 'https://aloeducation.com/language-prep/moi', 'ALO Education Guidance', 'University-specific waiver guidance; review required', 'needs_review', 'MOI Guidance | Medium of Instruction for Study Abroad | ALO Education', 'MOI guidance resource — understand when universities accept Medium of Instruction and verification requirements.', NULL, CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)
