SELECT 'test-cambridge-english', 'cambridge-english', 'CAE / CPE — Cambridge English', 'CAE / CPE', 'C1 Advanced and C2 Proficiency qualifications for advanced academic English.', 'Cambridge C1 Advanced (formerly CAE) and C2 Proficiency (formerly CPE) assess advanced English through Reading and Use of English, Writing, Listening and Speaking. Choose the qualification and required score specified by your institution; these qualifications are not interchangeable with a UKVI SELT.', 'english_proficiency', 'Cambridge University Press & Assessment', 'https://www.cambridgeenglish.org/exams-and-tests/qualifications/', 'Digital or paper at an authorised centre', 235, 'C1 Advanced about 3h 55m; C2 Proficiency about 3h 56m (paired speaking).', 'Cambridge English Scale: C1 certificate range 180–199; C2 certificate range 200–230.', 'Digital: 5–10 working days; paper: normally 4–6 weeks.', 'https://www.cambridgeenglish.org/exams-and-tests/qualifications/results/', 'Fees depend on location, delivery mode and booking date. View the provider booking price before payment.', 'Certificates do not expire; receiving institutions can set recency requirements.', 'Advanced academic English where the named qualification is accepted.', 'Confirm the exact exam, delivery mode and minimum score with your university. Visa evidence rules are separate; a university offer does not confirm visa eligibility.', 'Advanced / proficient', 'active', 0, 0, 10, 'Cambridge English official guidance', 'Official-source editorial review', 'verified', 'Cambridge CAE / CPE Preparation | ALO Education', 'Compare C1 Advanced and C2 Proficiency formats, score reporting and preparation guidance with ALO Education.', '2026-10-26 00:00:00.000', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)
WHERE NOT EXISTS (SELECT 1 FROM `english_tests` WHERE `slug` = 'cambridge-english' OR `id` = 'test-cambridge-english');
